window.AUTH=window.AUTH||{};window.AUTH["21-1052"]={"d":"21-1052","id":"2022/21-1052","n":"U.S., ex rel. Polansky v. Executive Health Resources","briefs":[{"k":"petitioner","label":"Brief of petitioner United States, ex rel. Jesse Polansky, M.D., M.P.H.","date":"2022-08-26","url":"https://www.supremecourt.gov/DocketPDF/21/21-1052/236527/20220826234222199_21-1052%20ts.pdf","side":"pet","n":43},{"k":"respondent","label":"Brief of respondent United States","date":"2022-10-17","url":"https://www.supremecourt.gov/DocketPDF/21/21-1052/243296/20221017173204608_21-1052tsUnitedStates.pdf","side":"res","n":51},{"k":"respondent","label":"Brief of respondent Executive Health Resources, Inc.","date":"2022-10-17","url":"https://www.supremecourt.gov/DocketPDF/21/21-1052/243254/20221017131159333_No.%2021-1052%20Brief%20of%20Respondent.pdf","side":"res","n":62},{"k":"reply","label":"Reply of petitioner United States, ex rel. Jesse Polansky, M.D., M.P.H.","date":"2022-11-16","url":"https://www.supremecourt.gov/DocketPDF/21/21-1052/246770/20221117105536096_21-1052%20rb%20--%20FILED.pdf","side":"pet","n":34}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/599us1r40_q8l1.pdf","tr":true,"items":[{"t":"case","label":"Carpenter v. United States","cite":"138 S. Ct. 2206","y":2018,"id":"2017/16-402","sc":1,"sum":"The Court held that the warrantless seizure and search of cell phone records revealing the location and movements of a cell phone user over the course of 127 days violates the Fourth Amendment.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Department of Commerce v. New York","cite":"139 S. Ct. 2551","y":2019,"id":"2018/18-966","sc":1,"op":1,"sum":"The Secretary did not violate the Enumeration Clause or the Census Act in deciding to reinstate a citizenship question on the 2020 census questionnaire, but the District Court was warranted in remanding the case back to the agency where the evidence tells a story that does not match the Secretary’s explanation for his decision.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"33"}},{"t":"case","label":"Hoyte v. Am. Nat’l Red Cross","cite":"518 F.3d 61","y":2008,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/518/61/","by":{"0":"38","1":"34"}},{"t":"case","label":"Logan v. Zimmerman Brush Co.","cite":"455 U.S. 422","y":1982,"id":"1981/80-5950","sc":1,"sum":"The judgment is reversed, and the case is remanded. 82 Ill. 2d 99, 411 N. E. 2d 277, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40","3":"21"}},{"t":"case","label":"Nicholas v. Penn. State Univ.","cite":"227 F.3d 133","y":2000,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/227/133/","by":{"0":"41"}},{"t":"case","label":"NLRB v. Noel Canning","cite":"573 U.S. 513","y":2014,"id":"2013/12-1281","sc":1,"sum":"A case in which the Court further defined the limitations on the presidential powers granted by the Recess Appointments Clause.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Ridenour v. Kaiser-Hill Co.","cite":"397 F.3d 925","y":2005,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/397/925/","by":{"0":"28, 31, 37","1":"34","2":"8, 29"}},{"t":"case","label":"Rita v. United States","cite":"551 U.S. 338","y":2007,"id":"2006/06-5754","sc":1,"sum":"The Court ruled that courts of appeals may apply a nonbinding presumption of reasonableness to within-Guidelines sentences. Justice Stephen Breyer wrote the opinion for the 8-1 majority.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21","2":"17, 43"}},{"t":"case","label":"Salinas v. United States R.R. Ret. Bd.","cite":"141 S. Ct. 691","y":2021,"id":"2020/19-199","sc":1,"sum":"The U. S. Railroad Retirement Board’s denial of a request to reopen a prior benefits determination under the Railroad Retirement Act of 1974 and the Railroad Unemployment Insurance Act is subject to judicial review.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"21","3":"3"}},{"t":"case","label":"Swift v. United States","cite":"318 F.3d 250","y":2003,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/318/250/","sum":"Describing “the question whether the False Claims Act requires the government to intervene before dismissing an action” as “largely academic”.","sumSrc":"brief:1","by":{"0":"35, 38","1":"21, 26, 29, 40, 44, 45","2":"17, 19, 20, 45, 47"}},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"op":1,"sum":"The Court held that a discovery rule does not govern section 1681p of FCRA, as that section explicitly delineated the exceptional case in which discovery triggered the two-year limitation and Adelaide's case does not fall within the exceptional category. The Court reasoned that it was not at liberty to make Congress' explicit exception the general rule.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"United States ex rel. Borzilleri v. Bayer Healthcare Pharm., Inc.","cite":"24 F.4th 32","y":2022,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.4th/24/32/","by":{"0":"39","2":"44"}},{"t":"case","label":"United States ex rel. Eisenstein v. City of New York","cite":"556 U.S. 928","y":2009,"id":"2008/08-660","sc":1,"op":4,"sum":"The Court held that the 30-day limit for filing a claim under the False Claims Act applies when the United States is not a party to the lawsuit.","sumSrc":"Oyez","by":{"0":"14","1":"passim","2":"5, 44","3":"3, 5, 9"}},{"t":"case","label":"United States ex rel. Graves v. ICANN","cite":"398 F. Supp. 3d 1307","y":2019,"court":"N.D. Ga.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/398/1307/","by":{"0":"36"}},{"t":"case","label":"United States ex rel. Kelly v. Boeing Co.","cite":"9 F.3d 743","y":1993,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/9/743/","by":{"0":"15","2":"8, 29, 31, 36","3":"19"}},{"t":"case","label":"United States ex rel. Poteet v. Medtronic, Inc.","cite":"552 F.3d 503","y":2009,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/552/503/","by":{"0":"19","1":"8"}},{"t":"case","label":"United States ex rel. Schweizer v. Oce N.V.","cite":"677 F.3d 1228","y":2012,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/677/1228/","by":{"0":"37, 39"}},{"t":"case","label":"United States ex rel. Sequoia Orange Co. v. Baird-Neece Packing Corp.","cite":"151 F.3d 1139","y":1998,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/151/1139/","sum":"Declaring Rule 41 inapplicable because it “protects defendants from vexatious plaintiffs,” whereas in the context of an FCA dismissal, “the plaintiffs, or relators, seek protection from the dismissal decision of the real party in interest, the government, under a specific statute establishing unique relationships among the parties”.","sumSrc":"brief:0","by":{"0":"passim","1":"14, 28, 33, 41, 42","2":"43, 47"}},{"t":"case","label":"United States ex rel. Thrower v. Academy Mortg. Corp.","cite":"968 F.3d 996","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/968/996/","by":{"0":"22, 31, 32"}},{"t":"case","label":"United States v. EMD Serono, Inc.","cite":"370 F. Supp. 3d 483","y":2019,"court":"E.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/370/483/","by":{"0":"36"}},{"t":"case","label":"United States v. Health Possibilities, P.S.C.","cite":"207 F.3d 335","y":2000,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/207/335/","by":{"0":"15, 27, 32","1":"25"}},{"t":"case","label":"Vermont Agency of Nat. Res. v. United States ex rel. Stevens","cite":"529 U.S. 765","y":2000,"id":"1999/98-1828","sc":1,"op":3,"sum":"The Court held that a private individual has standing to bring suit in federal court on behalf of the United States under the False Claims Act, but that the False Claims Act does not subject a state or state agency to liability in such actions. The Court concluded that the False Claims Act does not include states as \"persons\" who can be sued under the law.","sumSrc":"Oyez","by":{"0":"passim","1":"3, 23, 24, 35","2":"5, 7, 21, 23, 24, 40, 48","3":"9, 17"}},{"t":"case","label":"Zivotofsky ex rel. Zivotofsky v. Kerry","cite":"576 U.S. 1","y":2015,"id":"2014/13-628","sc":1,"sum":"The Court held that a federal statute directing the Secretary of State to record the birthplace of a citizen born in Jerusalem as “Israel” if requested to do so impermissibly infringed on the President’s power to recognize foreign states.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"31 U.S.C. § 3729","url":"https://www.law.cornell.edu/uscode/text/31/3729","subs":["(a)(1)(A)","(a)(1)(B)","(a)(1)(G)","(a)(1)","(a)(2)"],"stext":{"head":"§3729. False claims","paras":[[0,"(a) Liability for Certain Acts.—"],[1,"(1) In general.—Subject to paragraph (2), any person who—"],[2,"(A) knowingly presents, or causes to be presented, a false or fraudulent claim for payment or approval;"],[2,"(B) knowingly makes, uses, or causes to be made or used, a false record or statement material to a false or fraudulent claim;"],[2,"(C) conspires to commit a violation of subparagraph (A), (B), (D), (E), (F), or (G);"],[2,"(D) has possession, custody, or control of property or money used, or to be used, by the Government and knowingly delivers, or causes to be delivered, less than all of that money or property;"],[2,"(E) is authorized to make or deliver a document certifying receipt of property used, or to be used, by the Government and, intending to defraud the Government, makes or delivers the receipt without completely knowing that the information on the receipt is true;"],[2,"(F) knowingly buys, or receives as a pledge of an obligation or debt, public property from an officer or employee of the Government, or a member of the Armed Forces, who lawfully may not sell or pledge property; or"],[2,"(G) knowingly makes, uses, or causes to be made or used, a false record or statement material to an obligation to pay or transmit money or property to the Government, or knowingly conceals or knowingly and improperly avoids or decreases an obligation to pay or transmit money or property to the Government,"],[1,"is liable to the United States Government for a civil penalty of not less than $5,000 and not more than $10,000, as adjusted by the Federal Civil Penalties Inflation Adjustment Act of 1990 (28 U.S.C. 2461 note; Public Law 104–410 1), plus 3 times the amount of damages which the Government sustains because of the act of that person."],[1,"(2) Reduced damages.—If the court finds that—"],[2,"(A) the person committing the violation of this subsection furnished officials of the United States responsible for investigating false claims violations with all information known to such person about the violation within 30 days after the date on which the defendant first obtained the information;"],[2,"(B) such person fully cooperated with any Government investigation of such violation; and"],[2,"(C) at the time such person furnished the United States with the information about the violation, no criminal prosecution, civil action, or administrative action had commenced under this title with respect to such violation, and the person did not have actual knowledge of the existence of an investigation into such violation,"],[1,"the court may assess not less than 2 times the amount of damages which the Government sustains because of the act of that person."],[1,"(3) Costs of civil actions.—A person violating this subsection shall also be liable to the United States Government for the costs of a civil action brought to recover any such penalty or damages."],[0,"(b) Definitions.—For purposes of this section—"],[1,"(1) the terms \"knowing\" and \"knowingly\"—"],[2,"(A) mean that a person, with respect to information—"],[3,"(i) has actual knowledge of the information;"],[3,"(ii) acts in deliberate ignorance of the truth or falsity of the information; or"],[3,"(iii) acts in reckless disregard of the truth or falsity of the information; and"],[2,"(B) require no proof of specific intent to defraud;"],[1,"(2) the term \"claim\"—"],[2,"(A) means any request or demand, whether under a contract or otherwise, for money or property and whether or not the United States has title to the money or property, that—"],[3,"(i) is presented to an officer, employee, or agent of the United States; or"],[3,"(ii) is made to a contractor, grantee, or other recipient, if the money or property is to be spent or used on the Government's behalf or to advance a Government program or interest, and if the United States Government—"],[4,"(I) provides or has provided any portion of the money or property requested or demanded; or"],[4,"(II) will reimburse such contractor, grantee, or other recipient for any portion of the money or property which is requested or demanded; and"],[2,"(B) does not include requests or demands for money or property that the Government has paid to an individual as compensation for Federal employment or as an income subsidy with no restrictions on that individual's use of the money or property;"],[1,"(3) the term \"obligation\" means an established duty, whether or not fixed, arising from an express or implied contractual, grantor-grantee, or licensor-licensee relationship, from a fee-based or similar relationship, from statute or regulation, or from the retention of any overpayment; and"],[1,"(4) the term \"material\" means having a natural tendency to influence, or be capable of influencing, the payment or receipt of money or property."],[0,"(c) Exemption From Disclosure.—Any information furnished pursuant to subsection (a)(2) shall be exempt from disclosure under section 552 of title 5."],[0,"(d) Exclusion.—This section does not apply to claims, records, or statements made under the Internal Revenue Code of 1986."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/31/3729?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§3729. False claims","tname":"Money and Finance","by":{"0":"passim, 5, 5, 5","1":"2, passim, passim, passim","2":"6","3":"passim"}},{"t":"usc","label":"31 U.S.C. § 3730","url":"https://www.law.cornell.edu/uscode/text/31/3730","subs":["(b)(2)","(b)(3)","(b)(4)","(b)(4)(A)","(b)(4)(B)","(c)(1)","(c)(2)(A)","(c)(3)","(c)(4)","(c)(5)","(d)(1)","(b)(1)","(c)(2)","(c)(2)(B)","(c)(2)(C)","(c)(2)(D)","(d)","(d)(2)","(d)(3)","(d)(4)"],"stext":{"head":"§3730. Civil actions for false claims","paras":[[0,"(a) Responsibilities of the Attorney General.—The Attorney General diligently shall investigate a violation under section 3729. If the Attorney General finds that a person has violated or is violating section 3729, the Attorney General may bring a civil action under this section against the person."],[0,"(b) Actions by Private Persons.—(1) A person may bring a civil action for a violation of section 3729 for the person and for the United States Government. The action shall be brought in the name of the Government. The action may be dismissed only if the court and the Attorney General give written consent to the dismissal and their reasons for consenting."],[0,"(2) A copy of the complaint and written disclosure of substantially all material evidence and information the person possesses shall be served on the Government pursuant to Rule 4(d)(4) 1 of the Federal Rules of Civil Procedure. The complaint shall be filed in camera, shall remain under seal for at least 60 days, and shall not be served on the defendant until the court so orders. The Government may elect to intervene and proceed with the action within 60 days after it receives both the complaint and the material evidence and information."],[0,"(3) The Government may, for good cause shown, move the court for extensions of the time during which the complaint remains under seal under paragraph (2). Any such motions may be supported by affidavits or other submissions in camera. The defendant shall not be required to respond to any complaint filed under this section until 20 days after the complaint is unsealed and served upon the defendant pursuant to Rule 4 of the Federal Rules of Civil Procedure."],[0,"(4) Before the expiration of the 60-day period or any extensions obtained under paragraph (3), the Government shall—"],[1,"(A) proceed with the action, in which case the action shall be conducted by the Government; or"],[1,"(B) notify the court that it declines to take over the action, in which case the person bringing the action shall have the right to conduct the action."],[0,"(5) When a person brings an action under this subsection, no person other than the Government may intervene or bring a related action based on the facts underlying the pending action."],[0,"(c) Rights of the Parties to Qui Tam Actions.—(1) If the Government proceeds with the action, it shall have the primary responsibility for prosecuting the action, and shall not be bound by an act of the person bringing the action. Such person shall have the right to continue as a party to the action, subject to the limitations set forth in paragraph (2)."],[0,"(2)(A) The Government may dismiss the action notwithstanding the objections of the person initiating the action if the person has been notified by the Government of the filing of the motion and the court has provided the person with an opportunity for a hearing on the motion."],[0,"(B) The Government may settle the action with the defendant notwithstanding the objections of the person initiating the action if the court determines, after a hearing, that the proposed settlement is fair, adequate, and reasonable under all the circumstances. Upon a showing of good cause, such hearing may be held in camera."],[0,"(C) Upon a showing by the Government that unrestricted participation during the course of the litigation by the person initiating the action would interfere with or unduly delay the Government's prosecution of the case, or would be repetitious, irrelevant, or for purposes of harassment, the court may, in its discretion, impose limitations on the person's participation, such as—"],[1,"(i) limiting the number of witnesses the person may call;"],[1,"(ii) limiting the length of the testimony of such witnesses;"],[1,"(iii) limiting the person's cross-examination of witnesses; or"],[1,"(iv) otherwise limiting the participation by the person in the litigation."],[0,"(D) Upon a showing by the defendant that unrestricted participation during the course of the litigation by the person initiating the action would be for purposes of harassment or would cause the defendant undue burden or unnecessary expense, the court may limit the participation by the person in the litigation."],[0,"(3) If the Government elects not to proceed with the action, the person who initiated the action shall have the right to conduct the action. If the Government so requests, it shall be served with copies of all pleadings filed in the action and shall be supplied with copies of all deposition transcripts (at the Government's expense). When a person proceeds with the action, the court, without limiting the status and rights of the person initiating the action, may nevertheless permit the Government to intervene at a later date upon a showing of good cause."],[0,"(4) Whether or not the Government proceeds with the action, upon a showing by the Government that certain actions of discovery by the person initiating the action would interfere with the Government's investigation or prosecution of a criminal or civil matter arising out of the same facts, the court may stay such discovery for a period of not more than 60 days. Such a showing shall be conducted in camera. The court may extend the 60-day period upon a further showing in camera that the Government has pursued the criminal or civil investigation or proceedings with reasonable diligence and any proposed discovery in the civil action will interfere with the ongoing criminal or civil investigation or proceedings."],[0,"(5) Notwithstanding subsection (b), the Government may elect to pursue its claim through any alternate remedy available to the Government, including any administrative proceeding to determine a civil money penalty. If any such alternate remedy is pursued in another proceeding, the person initiating the action shall have the same rights in such proceeding as such person would have had if the action had continued under this section. Any finding of fact or conclusion of law made in such other proceeding that has become final shall be conclusive on all parties to an action under this section. For purposes of the preceding sentence, a finding or conclusion is final if it has been finally determined on appeal to the appropriate court of the United States, if all time for filing such an appeal with respect to the finding or conclusion has expired, or if the finding or conclusion is not subject to judicial review."],[0,"(d) Award to Qui Tam Plaintiff.—(1) If the Government proceeds with an action brought by a person under subsection (b), such person shall, subject to the second sentence of this paragraph, receive at least 15 percent but not more than 25 percent of the proceeds of the action or settlement of the claim, depending upon the extent to which the person substantially contributed to the prosecution of the action. Where the action is one which the court finds to be based primarily on disclosures of specific information (other than information provided by the person bringing the action) relating to allegations or transactions in a criminal, civil, or administrative hearing, in a congressional, administrative, or Government 2 Accounting Office report, hearing, audit, or investigation, or from the news media, the court may award such sums as it considers appropriate, but in no case more than 10 percent of the proceeds, taking into account the significance of the information and the role of the person bringing the action in advancing the case to litigation. Any payment to a person under the first or second sentence of this paragraph shall be made from the proceeds. Any such person shall also receive an amount for reasonable expenses which the court finds to have been necessarily incurred, plus reasonable attorneys' fees and costs. All such expenses, fees, and costs shall be awarded against the defendant."],[0,"(2) If the Government does not proceed with an action under this section, the person bringing the action or settling the claim shall receive an amount which the court decides is reasonable for collecting the civil penalty and damages. The amount shall be not less than 25 percent and not more than 30 percent of the proceeds of the action or settlement and shall be paid out of such proceeds. Such person shall also receive an amount for reasonable expenses which the court finds to have been necessarily incurred, plus reasonable attorneys' fees and costs. All such expenses, fees, and costs shall be awarded against the defendant."],[0,"(3) Whether or not the Government proceeds with the action, if the court finds that the action was brought by a person who planned and initiated the violation of section 3729 upon which the action was brought, then the court may, to the extent the court considers appropriate, reduce the share of the proceeds of the action which the person would otherwise receive under paragraph (1) or (2) of this subsection, taking into account the role of that person in advancing the case to litigation and any relevant circumstances pertaining to the violation. If the person bringing the action is convicted of criminal conduct arising from his or her role in the violation of section 3729, that person shall be dismissed from the civil action and shall not receive any share of the proceeds of the action. Such dismissal shall not prejudice the right of the United States to continue the action, represented by the Department of Justice."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/31/3730?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§3730. Civil actions for false claims","tname":"Money and Finance","by":{"0":"5, 23, 28, 5, 28, 14, 19, 20, 15, 19, 20, 32, 25, passim, passim, 21, 31, 30, 31, 7","1":"passim, 31, 31, 31, 31, 31, 31, 31, 31, 31, 38, 39, 38, 39, 38, 39, 38, 39, 38, 39, 38, 39, 38, 39, 12, 18, 22, 26, 12, 18, 22, 26, 12, 18, 22, 26","3":"20, passim, passim, passim, passim, 4, 8, 8, passim, 3, 4, 6, 15, 15"}},{"t":"usc","label":"31 U.S.C. § 3733","url":"https://www.law.cornell.edu/uscode/text/31/3733","subs":["(a)(1)"],"stext":{"head":"§3733. Civil investigative demands","paras":[[0,"(a) In General.—"],[1,"(1) Issuance and service.—Whenever the Attorney General, or a designee (for purposes of this section), has reason to believe that any person may be in possession, custody, or control of any documentary material or information relevant to a false claims law investigation, the Attorney General, or a designee, may, before commencing a civil proceeding under section 3730(a) or other false claims law, or making an election under section 3730(b), issue in writing and cause to be served upon such person, a civil investigative demand requiring such person—"],[2,"(A) to produce such documentary material for inspection and copying,"],[2,"(B) to answer in writing written interrogatories with respect to such documentary material or information,"],[2,"(C) to give oral testimony concerning such documentary material or information, or"],[2,"(D) to furnish any combination of such material, answers, or testimony."],[1,"The Attorney General may delegate the authority to issue civil investigative demands under this subsection. Whenever a civil investigative demand is an express demand for any product of discovery, the Attorney General, the Deputy Attorney General, or an Assistant Attorney General shall cause to be served, in any manner authorized by this section, a copy of such demand upon the person from whom the discovery was obtained and shall notify the person to whom such demand is issued of the date on which such copy was served. Any information obtained by the Attorney General or a designee of the Attorney General under this section may be shared with any qui tam relator if the Attorney General or designee determine it is necessary as part of any false claims act 1 investigation."],[1,"(2) Contents and deadlines.—"],[2,"(A) Each civil investigative demand issued under paragraph (1) shall state the nature of the conduct constituting the alleged violation of a false claims law which is under investigation, and the applicable provision of law alleged to be violated."],[2,"(B) If such demand is for the production of documentary material, the demand shall—"],[3,"(i) describe each class of documentary material to be produced with such definiteness and certainty as to permit such material to be fairly identified;"],[3,"(ii) prescribe a return date for each such class which will provide a reasonable period of time within which the material so demanded may be assembled and made available for inspection and copying; and"],[3,"(iii) identify the false claims law investigator to whom such material shall be made available."],[2,"(C) If such demand is for answers to written interrogatories, the demand shall—"],[3,"(i) set forth with specificity the written interrogatories to be answered;"],[3,"(ii) prescribe dates at which time answers to written interrogatories shall be submitted; and"],[3,"(iii) identify the false claims law investigator to whom such answers shall be submitted."],[2,"(D) If such demand is for the giving of oral testimony, the demand shall—"],[3,"(i) prescribe a date, time, and place at which oral testimony shall be commenced;"],[3,"(ii) identify a false claims law investigator who shall conduct the examination and the custodian to whom the transcript of such examination shall be submitted;"],[3,"(iii) specify that such attendance and testimony are necessary to the conduct of the investigation;"],[3,"(iv) notify the person receiving the demand of the right to be accompanied by an attorney and any other representative; and"],[3,"(v) describe the general purpose for which the demand is being issued and the general nature of the testimony, including the primary areas of inquiry, which will be taken pursuant to the demand."],[2,"(E) Any civil investigative demand issued under this section which is an express demand for any product of discovery shall not be returned or returnable until 20 days after a copy of such demand has been served upon the person from whom the discovery was obtained."],[2,"(F) The date prescribed for the commencement of oral testimony pursuant to a civil investigative demand issued under this section shall be a date which is not less than seven days after the date on which demand is received, unless the Attorney General or an Assistant Attorney General designated by the Attorney General determines that exceptional circumstances are present which warrant the commencement of such testimony within a lesser period of time."],[2,"(G) The Attorney General shall not authorize the issuance under this section of more than one civil investigative demand for oral testimony by the same person unless the person requests otherwise or unless the Attorney General, after investigation, notifies that person in writing that an additional demand for oral testimony is necessary."],[0,"(b) Protected Material or Information.—"],[1,"(1) In general.—A civil investigative demand issued under subsection (a) may not require the production of any documentary material, the submission of any answers to written interrogatories, or the giving of any oral testimony if such material, answers, or testimony would be protected from disclosure under—"],[2,"(A) the standards applicable to subpoenas or subpoenas duces tecum issued by a court of the United States to aid in a grand jury investigation; or"],[2,"(B) the standards applicable to discovery requests under the Federal Rules of Civil Procedure, to the extent that the application of such standards to any such demand is appropriate and consistent with the provisions and purposes of this section."],[1,"(2) Effect on other orders, rules, and laws.—Any such demand which is an express demand for any product of discovery supersedes any inconsistent order, rule, or provision of law (other than this section) preventing or restraining disclosure of such product of discovery to any person. Disclosure of any product of discovery pursuant to any such express demand does not constitute a waiver of any right or privilege which the person making such disclosure may be entitled to invoke to resist discovery of trial preparation materials."],[0,"(c) Service; Jurisdiction.—"],[1,"(1) By whom served.—Any civil investigative demand issued under subsection (a) may be served by a false claims law investigator, or by a United States marshal or a deputy marshal, at any place within the territorial jurisdiction of any court of the United States."],[1,"(2) Service in foreign countries.—Any such demand or any petition filed under subsection (j) may be served upon any person who is not found within the territorial jurisdiction of any court of the United States in such manner as the Federal Rules of Civil Procedure prescribe for service in a foreign country. To the extent that the courts of the United States can assert jurisdiction over any such person consistent with due process, the United States District Court for the District of Columbia shall have the same jurisdiction to take any action respecting compliance with this section by any such person that such court would have if such person were personally within the jurisdiction of such court."],[0,"(d) Service Upon Legal Entities and Natural Persons.—"],[1,"(1) Legal entities.—Service of any civil investigative demand issued under subsection (a) or of any petition filed under subsection (j) may be made upon a partnership, corporation, association, or other legal entity by—"],[2,"(A) delivering an executed copy of such demand or petition to any partner, executive officer, managing agent, or general agent of the partnership, corporation, association, or entity, or to any agent authorized by appointment or by law to receive service of process on behalf of such partnership, corporation, association, or entity;"],[2,"(B) delivering an executed copy of such demand or petition to the principal office or place of business of the partnership, corporation, association, or entity; or"],[2,"(C) depositing an executed copy of such demand or petition in the United States mails by registered or certified mail, with a return receipt requested, addressed to such partnership, corporation, association, or entity at its principal office or place of business."],[1,"(2) Natural persons.—Service of any such demand or petition may be made upon any natural person by—"],[2,"(A) delivering an executed copy of such demand or petition to the person; or"],[2,"(B) depositing an executed copy of such demand or petition in the United States mails by registered or certified mail, with a return receipt requested, addressed to the person at the person's residence or principal office or place of business."],[0,"(e) Proof of Service.—A verified return by the individual serving any civil investigative demand issued under subsection (a) or any petition filed under subsection (j) setting forth the manner of such service shall be proof of such service. In the case of service by registered or certified mail, such return shall be accompanied by the return post office receipt of delivery of such demand."],[0,"(f) Documentary Material.—"],[1,"(1) Sworn certificates.—The production of documentary material in response to a civil investigative demand served under this section shall be made under a sworn certificate, in such form as the demand designates, by—"],[2,"(A) in the case of a natural person, the person to whom the demand is directed, or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/31/3733?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3733. Civil investigative demands","tname":"Money and Finance","by":{"0":"28"}},{"t":"rule","label":"Fed. R. Civ. P. 24","url":"https://www.law.cornell.edu/rules/frcp/rule_24","subs":["(b)"],"by":{"0":"25"}},{"t":"rule","label":"Fed. R. Crim. P. 48","url":"https://www.law.cornell.edu/rules/frcrmp/rule_48","subs":["(a)"],"by":{"0":"39"}},{"t":"case","label":"Allison Engine Co. v. United States ex rel. Sanders","cite":"553 U.S. 662","y":2008,"id":"2007/07-214","sc":1,"sum":"Writing for a unanimous Court, Justice Samuel A. Alito made clear that a plaintiff must prove more than that the false statement's use resulted in payment or approval or that Government money was used to pay the claim. Instead, a plaintiff must show that the defendant intended the false statement to be \"material\" to the Government's decision to pay or approve the false claim.","sumSrc":"Oyez","by":{"1":"19, 20, 40, 44"}},{"t":"case","label":"Barton v. Barr","cite":"140 S. Ct. 1442","y":2020,"id":"2019/18-725","sc":1,"sum":"The Court held that in determining eligibility for cancellation of removal of a lawful permanent resident who commits a serious crime, an offense listed in 8 U.S.C. § 1182(a)(2) committed during the initial seven years of residence need not be one of the offenses of removal.","sumSrc":"Oyez","by":{"1":"22, 25"}},{"t":"case","label":"County of Sacramento v. Lewis","cite":"523 U.S. 833","y":1998,"id":"1997/96-1337","sc":1,"ar":2,"sum":"In a unanimous decision the Court first ruled that the Fourth Amendment's reasonableness standards prevented its illegal seizure protections from applying to high-speed police chases. Such incidents are merely pursuits and do not constitute actual seizures, especially if they fail due to the death of the subject.","sumSrc":"Oyez","by":{"1":"41, 42","2":"48"}},{"t":"case","label":"Heckler v. Chaney","cite":"470 U.S. 821","y":1985,"id":"1984/83-1878","sc":1,"ar":4,"sum":"They are presumptively unreviewable. Refusals of administrative agencies to exercise enforcement authority involve a complicated balancing of factors, including agency allocation of scarce resources, which are not suitable for judicial review. Thus, they are presumptively \"committed to agency discretion by law\" under Section 701(a)(2).","sumSrc":"Oyez","by":{"1":"40, 43, 45","2":"4, 29, 34, 46"}},{"t":"case","label":"Kellogg Brown & Root Servs., Inc. v. United States ex rel. Carter","cite":"575 U.S. 650","y":2015,"id":"2014/12-1497","sc":1,"sum":"The Wartime Suspension of Limitations Act's statute of limitations tolling provision does not apply to claims of civil fraud brought by private parties. The False Claims Act's \"first-to-file bar\" keeps new claims out of court only while related claims are still alive, but not in perpetuity.","sumSrc":"Oyez","by":{"1":"passim","2":"1, 15","3":"9"}},{"t":"case","label":"Murphy v. Smith","cite":"138 S. Ct. 784","y":2018,"id":"2017/16-1067","sc":1,"sum":"A case in which the Court interpreted the parenthetical phrase “not to exceed 25 percent,” as used in 42 U.S.C. § 1997e(d)(2), to mean exactly 25 percent, thereby precluding the district court from exercising its discretion to allocate a lower percentage of the damage award to attorney's fees.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Rimini St., Inc. v. Oracle USA, Inc.","cite":"139 S. Ct. 873","y":2019,"id":"2018/17-1625","sc":1,"sum":"A federal district court’s discretion to award “full costs” to a party in copyright litigation pursuant to 17 U. S. C. §505 is limited to the six categories specified in the general costs statute codified at 28 U. S. C. §§1821 and 1920.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"22","2":"18"}},{"t":"case","label":"State Farm Fire & Cas. Co. v. United States ex rel. Rigsby","cite":"137 S. Ct. 436","y":2016,"id":"2016/15-513","sc":1,"sum":"The Court determined that a violation of the False Claims Act’s seal requirement does not mandate dismissal of the complaint.","sumSrc":"Oyez","by":{"1":"19, 40, 45","3":"3"}},{"t":"case","label":"United States v. Armstrong","cite":"517 U.S. 456","y":1996,"id":"1995/95-157","sc":1,"ar":1,"sum":"Announced by Chief Justice William H. Rehnquist, the Court held that in order to file selective-prosecution claims, defendants must show that the government failed to prosecute similarly situated suspects of other races. \"If the claim . . . were well founded,\" wrote Rehnquist, \"it should not have been an insuperable task to prove that persons of a different race were not prosecuted.\".","sumSrc":"Oyez","by":{"1":"41","2":"46, 47"}},{"t":"case","label":"United States v. Whyte","cite":"918 F.3d 339","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/918/339/","by":{"1":"18"}},{"t":"case","label":"United States ex rel. CIMZNHCA, LLC v. UCB, Inc.","cite":"970 F.3d 835","y":2020,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/970/835/","op":1,"sum":"Explaining that the Paragraph 3 clause “instructs the district court not to limit the relator's `status and rights' as they are defned by” Para- Pgraaphgs e1 anPd 2r.","sumSrc":"opinion","by":{"1":"8, 28, 30, 31","2":"22, 34","3":"passim"}},{"t":"case","label":"United States ex rel. Sequoia Orange Co. v. Sunland Packing House Co.","cite":"912 F. Supp. 1325","y":1995,"court":"E.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp./912/1325/","by":{"1":"33, 34, 35","3":"14"}},{"t":"case","label":"United States ex rel. Stierli v. Shasta Servs. Inc.","cite":"440 F. Supp. 2d 1108","y":2006,"court":"E.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/440/1108/","by":{"1":"34"}},{"t":"const","label":"Article II, Section 3","clauses":[["take-care","Take Care Clause"]],"text":"He shall from time to time give to the Congress Information of the State of the Union, and recommend to their Consideration such Measures as he shall judge necessary and expedient; he may, on extraordinary Occasions, convene both Houses, or either of them, and in Case of Disagreement between them, with Respect to the Time of Adjournment, he may adjourn them to such Time as he shall think proper; he shall receive Ambassadors and other public Ministers; he shall take Care that the Laws be faithfully executed, and shall Commission all the Officers of the United States.","by":{"1":"40","2":"2, 4","3":"passim"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","by":{"1":"43"}},{"t":"usc","label":"31 U.S.C. § 3731","url":"https://www.law.cornell.edu/uscode/text/31/3731","subs":["(c)","(c)(1)"],"by":{"1":"12, 18, 22, 26, 12, 18, 22, 26"}},{"t":"law","label":"Pub. L. No. 99-562","url":"https://www.govinfo.gov/link/statute/100/3153","by":{"1":"33","2":"6"}},{"t":"reg","label":"42 C.F.R. § 412.3","url":"https://www.ecfr.gov/current/title-42/section-412.3","subs":["(d)(1)"],"by":{"1":"4"}},{"t":"case","label":"Auffmordt v. Hedden","cite":"137 U.S. 310","y":1890,"id":"scdb/1890-035","sc":1,"sum":"On a reappraisement by a merchant appraiser and a general appraiser, under § 2930 of the Revised.Statutes, the valuation of goods entered in March, 1886, was raised, and the importer paid thereon additional duties, for which he sued the collector, after protest and appeal. At the trial, the plaintiff put in evidence chapter 3, part 8, articles 447 to 506, and chapter 5, part 8, articles 1399 to 1410, and 1415 to …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"37"}},{"t":"case","label":"Brooks v. Dunlop Mfg. Inc.","cite":"702 F.3d 624","y":2012,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/702/624/","by":{"2":"41"}},{"t":"case","label":"Buckley v. Valeo","cite":"424 U.S. 1","y":1976,"id":"1975/75-436","sc":1,"op":1,"sum":"The Court held that both upheld and struck down portions of the Federal Election Campaign Act of 1971. Restrictions on individual donations were not a violation of the donators' First Amendment rights; but certain restrictions of campaign expenditures did violate the First Amendment.","sumSrc":"Oyez","by":{"2":"4, 13, 25, 36, 37"}},{"t":"case","label":"Clinton v. Jones","cite":"520 U.S. 681","y":1997,"id":"1996/95-1853","sc":1,"sum":"The Court found that the President did not have immunity from civil litigation.","sumSrc":"Oyez","by":{"2":"32","3":"19"}},{"t":"case","label":"Cochise Consultancy, Inc. v. United States ex rel. Hunt","cite":"39 S. Ct. 1507","y":2019,"id":"2018/18-315","sc":1,"op":1,"sum":"The limitations period in 31 U. S. C. §3731(b)(2)—which provides that a False Claims Act action must be brought within 3 years after the “the official of the United States charged with responsibility to act in the circumstances” knew or should have known the relevant facts, but not more than 10 years after the violation—applies in a qui tam suit in which the Federal Government has declined to intervene; the relator in a nonintervened suit is not “the official of the United States” whose knowledge triggers §3731(b)(2)’s limitations period.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"35","3":"20"}},{"t":"case","label":"vi Cooter & Gell v. Hartmarx Corp.","cite":"496 U.S. 384","y":1990,"id":"1989/89-275","sc":1,"op":1,"sum":"Respondents, the defendants in a District Court suit instituted by petitioner law firm on behalf of a client, filed a motion to dismiss the complaint as having no basis in fact and a motion for sanctions under Federal Rule of Civil Procedure 11 on the ground that the firm had not made sufficient prefiling inquiries to support the complaint's allegations. Rule 11-after specifying, interalia, that an attorney's …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"44"}},{"t":"case","label":"Exxon Co., U.S.A. v. Sofec, Inc.","cite":"517 U.S. 830","y":1996,"id":"1995/95-129","sc":1,"sum":"The Court held that a plaintiff in admiralty that is the superseding cause of its own injury, and thus the sole, proximate cause, cannot recover part of its damages from tort-feasors or contracting partners whose blameworthy actions were causes in fact of the injury.","sumSrc":"Oyez","by":{"2":"50"}},{"t":"case","label":"Exxon Mobil Corp. v. Allapattah Servs., Inc.","cite":"545 U.S. 546","y":2005,"id":"2004/04-70","sc":1,"sum":"The Court ruled that as long one plaintiff meets the amount-in-controversy requirement for federal jurisdiction, Section 1367 authorizes federal courts to exercise supplemental jurisdiction over related claims even if they do not meet the requirement.","sumSrc":"Oyez","by":{"2":"41"}},{"t":"case","label":"Free Enter. Fund v. Pub. Co. Acct. Oversight Bd.","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"2":"26"}},{"t":"case","label":"Fuentes v. Shevin","cite":"407 U.S. 67","y":1972,"id":"1971/70-5039","sc":1,"sum":"Appellants, most of whom were purchasers of household goods under conditional sales contracts, challenge the constitutionality of prejudgment replevin provisions of Florida law (in No. 70-5039) and Pennsylvania law (in No. 70-5138). These provisions permit a private party, withouit a hearing or prior notice to the other party, to obtain a prejudgment writ of replevin through a summary process of ex parte application …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"44"}},{"t":"case","label":"Hughes Aircraft Co. v. United States ex rel. Schumer","cite":"520 U.S. 939","y":1997,"id":"1996/95-1340","sc":1,"sum":"The Court held that, because the 1986 amendment does not apply retroactively to qui tam suits regarding allegedly false claims submitted prior to its enactment, Schumer's action should have been dismissed, as required by the pre-1986 version of the FCA.","sumSrc":"Oyez","by":{"2":"28, 33, 39"}},{"t":"case","label":"INS v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"sum":"The Court held that the Immigration and Nationality Act violated the separation of powers by allowing a one-house veto over executive decisions.","sumSrc":"Oyez","by":{"2":"3"}},{"t":"case","label":"Jama v. Immigr. & Customs Enf’t","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"sum":"Federal immigration law permitted an alien to be removed to a country without the advance consent of that country's government. Of the four removal options federal immigration law listed, an acceptance requirement appeared in only one clause: \"...he shall be removed to another country whose government will accept him.\" That clause only applied after the attorney general attempted the prior deportation option.","sumSrc":"Oyez","by":{"2":"43"}},{"t":"case","label":"vii Lucia v. SEC","cite":"138 S. Ct. 2044","y":2018,"id":"2017/17-130","sc":1,"sum":"The Court decided that administrative law judges of the Securities and Exchange Commission are \"officers of the United States\" subject to the Constitution's Appointments Clause.","sumSrc":"Oyez","by":{"2":"35, 36"}},{"t":"case","label":"Mathews v. Eldridge","cite":"424 U.S. 319","y":1976,"id":"1975/74-204","sc":1,"sum":"In an 6-to-2 decision, the Court held that the initial termination of Eldridge's benefits without a hearing did not violate due process.","sumSrc":"Oyez","by":{"2":"48"}},{"t":"case","label":"Morrison v. Olson","cite":"487 U.S. 654","y":1988,"id":"1987/87-1279","sc":1,"ar":1,"sum":"The near-unanimous Court held that the means of selecting the independent counsel did not violate the Appointments Clause; the powers allocated to the special court did not violate Article III; and the Act was not offensive to the separation of powers doctrine since it did not impermissibly interfere with the functions of the Executive Branch.","sumSrc":"Oyez","by":{"2":"25, 26, 27, 31, 32, 37","3":"19"}},{"t":"case","label":"United States ex rel. Neher v. NEC Corp.","cite":"11 F.3d 136","y":1993,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/11/136/","by":{"2":"38"}},{"t":"case","label":"Newman v. United States","cite":"382 F.2d 479","y":1967,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/382/479/","by":{"2":"4, 30"}},{"t":"case","label":"PHH Corp. v. CFPB","cite":"881 F.3d 75","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/881/75/","by":{"2":"27"}},{"t":"case","label":"Riley v. St. Luke’s Episcopal Hosp.","cite":"196 F.3d 514","y":1999,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/196/514/","by":{"2":"7"}},{"t":"case","label":"Riley v. St. Luke’s Episcopal Hosp.","cite":"252 F.3d 749","y":2001,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/252/749/","op":2,"by":{"2":"6, 8, 29, 30, 32, 33, 34, 38","3":"17"}},{"t":"case","label":"Rinaldi v. United States","cite":"434 U.S. 22","y":1977,"id":"1977/76-6194","sc":1,"sum":"The District Court abused its discretion in denying the Government's motion to dismiss on the ground that the violation of the Petite policy resulted from prosecutonal misconduct rather than inadvertence. The salient issue is not whether the decision to prosecute was made in bad faith but rather whether the Government's later efforts to terminate the prosecution were similarly tainted with impropriety It does not …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"46"}},{"t":"case","label":"Seila Law LLC v. CFPB","cite":"140 S. Ct. 2183","y":2020,"id":"2019/19-7","sc":1,"op":1,"sum":"The Court held that the vesting of substantial executive authority in the Consumer Financial Protection Bureau, an independent agency led by a single director, violates the separation of powers, but the statutory provision creating that violation, 12 U.S.C. § 5491(c)(3) is severable from the Dodd-Frank Act.","sumSrc":"Oyez","by":{"2":"3, 4, 5, 24, 25, 27, 31","3":"20"}},{"t":"case","label":"Springer v. Philippine Islands","cite":"277 U.S. 189","y":1928,"id":"scdb/1927-161","sc":1,"sum":"1. Acts of the Philippine Legislature creating a coal company and a bank, the stock of which is largely owned by the Philippine government, provide that the power to vote the stock shall be vested in a \"Committee,\" in the one case, and in a \"Board of Control,\" in the other, each consisting of the Governor General, the President of the Senate, and the Speaker of the House of Representatives. Held, that the voting of …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"25"}},{"t":"case","label":"United States ex rel. Stevens v. Vt. Agency of Nat. Res.","cite":"162 F.3d 195","y":1998,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/162/195/","by":{"2":"23"}},{"t":"case","label":"United States ex rel. Taxpayers Against Fraud v. Gen. Elec. Co.","cite":"41 F.3d 1032","y":1994,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/41/1032/","op":1,"sum":"Noting, among other things, that “the government may take complete control of the case if it wishes”.","sumSrc":"brief:2","by":{"2":"36"}},{"t":"case","label":"United States v. Comstock","cite":"560 U.S. 126","y":2010,"id":"2009/08-1224","sc":1,"sum":"The Court held that the Necessary and Proper Clause granted Congress authority to enact the Adam Walsh Protection and Safety Act.","sumSrc":"Oyez","by":{"2":"40"}},{"t":"case","label":"United States v. Concord Mgmt. & Consulting, LLC","cite":"317 F. Supp. 3d 598","y":2018,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/317/598/","by":{"2":"26"}},{"t":"case","label":"United States v. Donziger","cite":"38 F.4th 290","y":2022,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/38/290/","sum":"Concluding that contempt prosecutor was “Officer of the United States,” but upholding appointment.","sumSrc":"brief:2","by":{"2":"38"}},{"t":"case","label":"United States v. Fokker Servs. B.V.","cite":"818 F.3d 733","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/818/733/","by":{"2":"30"}},{"t":"case","label":"ix United States v. Germaine","cite":"99 U.S. 508","y":1878,"id":"scdb/1878-198","sc":1,"sum":"1. Civil surgeons appointed by the Commissioner of Pensions under sect. 4777 of the Revised Statutes are not officers of the United States.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"37"}},{"t":"case","label":"United States v. Griswold","cite":"24 F. 361","y":1885,"court":"D. Or.","url":"https://www.courtlistener.com/c/F./24/361/","by":{"2":"41"}},{"t":"case","label":"United States v. Griswold","cite":"30 F. 762","y":1887,"court":"C.C.D. Or.","url":"https://www.courtlistener.com/c/F./30/762/","by":{"2":"41"}},{"t":"case","label":"United States v. Maurice","cite":"26 F. Cas. 1211","y":1823,"court":"C.C.D. Va.","url":"https://www.courtlistener.com/c/F.%20Cas./26/1211/","by":{"2":"38"}},{"t":"case","label":"United States v. Nixon","cite":"418 U.S. 683","y":1974,"id":"1973/73-1766","sc":1,"sum":"The Court held that the President does not have executive privilege in immunity from subpoenas or other civil court actions.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"United States v. San Jacinto Tin Co.","cite":"125 U.S. 273","y":1888,"id":"scdb/1887-183","sc":1,"sum":"A suit maybe brought by the United'States in any court of competent juris-. diction to set aside, cancel, or annul a patent for land issued in its name, on the ground that it was obtained by fraud or mistake.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"25"}},{"t":"case","label":"Gallardo ex rel. Vassallo v. Marstiller","cite":"142 S. Ct. 1751","y":2022,"id":"2021/20-1263","sc":1,"sum":"The Medicaid Act permits a State to seek reimbursement from settlement payments allocated for future medical care.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"17"}},{"t":"case","label":"Walz v. Tax Comm’n of N.Y.C.","cite":"397 U.S. 664","y":1970,"id":"1969/135","sc":1,"op":1,"sum":"In a 7-to-1 decision, the Court held that the exemptions did not violate the Establishment Clause. The Court held that the purpose of the exemptions was to neither advance nor inhibit religion; no one particular church or religious group had been singled out to receive tax exempt status.","sumSrc":"Oyez","by":{"2":"40"}},{"t":"case","label":"Washington v. Glucksberg","cite":"521 U.S. 702","y":1997,"id":"1996/96-110","sc":1,"op":1,"sum":"The Court decided that a law banning physician-assisted suicide does not violate the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"2":"47"}},{"t":"case","label":"West Virginia v. EPA","cite":"142 S. Ct. 2587","y":2022,"id":"2021/20-1530","sc":1,"sum":"Congress did not grant the Environmental Protection Agency in Section 111(d) of the Clean Air Act the authority to devise emissions caps based on the generation shifting approach the Agency took in the Clean Power Plan.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"22"}},{"t":"case","label":"Whitman v. Am. Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Yates v. Pinellas Hematology & Oncology, P.A.","cite":"21 F.4th 1288","y":2021,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/21/1288/","by":{"2":"28"}},{"t":"const","label":"Article II, Section 1","clauses":[["executive-vesting","Executive Vesting Clause"],["natural-born","Natural-Born Citizen Clause"]],"by":{"2":"4"}},{"t":"const","label":"Article II, Section 2, Clause 2","clauses":[["treaty","Treaty Clause"],["appointments","Appointments Clause"]],"text":"He shall have Power, by and with the Advice and Consent of the Senate, to make Treaties, provided two thirds of the Senators present concur; and he shall nominate, and by and with the Advice and Consent of the Senate, shall appoint Ambassadors, other public Ministers and Consuls, Judges of the supreme Court, and all other Officers of the United States, whose Appointments are not herein otherwise provided for, and which shall be established by Law: but the Congress may by Law vest the Appointment of such inferior Officers, as they think proper, in the President alone, in the Courts of Law, or in the Heads of Departments.","by":{"2":"35"}},{"t":"rule","label":"Fed. R. Civ. P. 41","url":"https://www.law.cornell.edu/rules/frcp/rule_41","subs":["(a)(1)"],"by":{"2":"44","3":"21"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"3":"17"}},{"t":"case","label":"Marvin v. Trout","cite":"199 U.S. 212","y":1905,"id":"scdb/1905-019","sc":1,"sum":"A certificate of the presiding judge of the state court made after the decision. to the effect that a Federal question was considered and decided, cannot confer jurisdiction on this court where the record does not otherwise show it to éxist.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"17"}},{"t":"case","label":"(I) Cases—continued: McCreary Cty. v. ACLU of Ky.","cite":"545 U.S. 844","y":2005,"id":"2004/03-1693","sc":1,"sum":"The Court found the display of the Ten Commandments in public schools and courthouses violated the Establishment Clause of the First Amendment.","sumSrc":"Oyez","by":{"3":"18"}},{"t":"case","label":"Printz v. United States","cite":"521 U.S. 898","y":1997,"id":"1996/95-1478","sc":1,"sum":"The Court held that Congress could not require state agencies to perform federal duties under the Necessary and Proper Clause.","sumSrc":"Oyez","by":{"3":"17"}},{"t":"case","label":"United States ex rel. Marcus v. Hess","cite":"317 U.S. 537","y":1943,"id":"scdb/1942-043","sc":1,"sum":"1. Section 5438 of the Revised Statutes, which subjects to the penalties therein prescribed \"Every person who.. causes to be presented, for payment... any claim upon or against the Government of the United States,... knowing such claim to be.. fraudulent...,\" held applicable to contractors who, by collusive bidding, obtained contracts with municipalities and school districts of a State for work on federal Public …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"18"}},{"t":"case","label":"United States v. Griswold","cite":"5 Sawy. 25","y":1877,"court":"D. Or.","url":"https://www.courtlistener.com/c/Sawy./5/25/","by":{"3":"14"}}]};